object Main {
    @JvmStatic
    fun main(args: Array<String>) {
        val thread = Thread(null, TaskAdapter(), "", 1L shl 27)
        thread.start()
        thread.join()
    }

    private class TaskAdapter : Runnable {
        override fun run() {
            val inputStream = System.`in`
            val outputStream = System.out
            val input = FastInput(inputStream)
            val output = FastOutput(outputStream)
            val solver = G2PlaylistForPolycarpHardVersion()
            solver.solve(1, input, output)
            output.close()
        }
    }

    private class G2PlaylistForPolycarpHardVersion {
        private val mod = Modular(1e9 + 7)

        fun solve(testNumber: Int, input: FastInput, output: FastOutput) {
            val n = input.readInt()
            val m = input.readInt()
            val musics = Array(n) { IntArray(2) }
            val counts = IntArray(4)

            for (i in 0 until n) {
                musics[i][0] = input.readInt()
                musics[i][1] = input.readInt()
                counts[musics[i][1]]++
            }

            val c1 = counts[1]
            val c2 = counts[2]
            val c3 = counts[3]

            val comp = Array(c1 + 1) {
                Array(c2 + 1) {
                    Array(c3 + 1) {
                        IntArray(4)
                    }
                }
            }

            for (i in 0..c1) {
                for (j in 0..c2) {
                    for (k in 0..c3) {
                        for (t in 0 until 4) {
                            if (i == 0 && j == 0 && k == 0) {
                                comp[i][j][k][t] = 1
                                continue
                            }

                            if (i > 0 && t != 1) {
                                comp[i][j][k][t] = mod.plus(
                                    comp[i][j][k][t],
                                    mod.mul(comp[i - 1][j][k][1], i)
                                )
                            }

                            if (j > 0 && t != 2) {
                                comp[i][j][k][t] = mod.plus(
                                    comp[i][j][k][t],
                                    mod.mul(comp[i][j - 1][k][2], j)
                                )
                            }

                            if (k > 0 && t != 3) {
                                comp[i][j][k][t] = mod.plus(
                                    comp[i][j][k][t],
                                    mod.mul(comp[i][j][k - 1][3], k)
                                )
                            }
                        }
                    }
                }
            }

            var last = Array(c1 + 1) {
                Array(c2 + 1) {
                    Array(c3 + 1) {
                        IntArray(m + 1)
                    }
                }
            }

            var next = Array(c1 + 1) {
                Array(c2 + 1) {
                    Array(c3 + 1) {
                        IntArray(m + 1)
                    }
                }
            }

            last[0][0][0][0] = 1
            var t1 = 0
            var t2 = 0
            var t3 = 0

            for (music in musics) {
                val type = music[1]
                val duration = music[0]

                when (type) {
                    1 -> t1++
                    2 -> t2++
                    else -> t3++
                }

                for (i in 0..t1) {
                    for (j in 0..t2) {
                        for (k in 0..t3) {
                            for (t in 0..m) {
                                next[i][j][k][t] = last[i][j][k][t]

                                if (t < duration) {
                                    continue
                                }

                                if (type == 1 && i > 0) {
                                    next[i][j][k][t] = mod.plus(
                                        next[i][j][k][t],
                                        last[i - 1][j][k][t - duration]
                                    )
                                } else if (type == 2 && j > 0) {
                                    next[i][j][k][t] = mod.plus(
                                        next[i][j][k][t],
                                        last[i][j - 1][k][t - duration]
                                    )
                                } else if (type == 3 && k > 0) {
                                    next[i][j][k][t] = mod.plus(
                                        next[i][j][k][t],
                                        last[i][j][k - 1][t - duration]
                                    )
                                }
                            }
                        }
                    }
                }

                val temporary = last
                last = next
                next = temporary
            }

            var answer = 0

            for (i in 0..c1) {
                for (j in 0..c2) {
                    for (k in 0..c3) {
                        answer = mod.plus(
                            answer,
                            mod.mul(last[i][j][k][m], comp[i][j][k][0])
                        )
                    }
                }
            }

            output.println(answer)
        }
    }

    private class Modular {
        private val m: Int

        constructor(m: Int) {
            this.m = m
        }

        constructor(m: Long) {
            this.m = m.toInt()
            if (this.m.toLong() != m) {
                throw IllegalArgumentException()
            }
        }

        constructor(m: Double) {
            this.m = m.toInt()
            if (this.m.toDouble() != m) {
                throw IllegalArgumentException()
            }
        }

        fun valueOf(value: Int): Int {
            var x = value % m
            if (x < 0) {
                x += m
            }
            return x
        }

        fun valueOf(value: Long): Int {
            var x = value % m
            if (x < 0) {
                x += m
            }
            return x.toInt()
        }

        fun mul(x: Int, y: Int): Int {
            return valueOf(x.toLong() * y)
        }

        fun plus(x: Int, y: Int): Int {
            return valueOf(x + y)
        }

        override fun toString(): String {
            return "mod $m"
        }
    }

    private class FastOutput : Closeable {
        private val cache = StringBuilder(10 shl 20)
        private val writer: Writer

        constructor(writer: Writer) {
            this.writer = writer
        }

        constructor(outputStream: OutputStream) : this(OutputStreamWriter(outputStream))

        fun println(value: Int): FastOutput {
            cache.append(value).append('\n')
            return this
        }

        fun flush(): FastOutput {
            try {
                writer.append(cache)
                writer.flush()
                cache.setLength(0)
            } catch (e: IOException) {
                throw UncheckedIOException(e)
            }
            return this
        }

        override fun close() {
            flush()
            try {
                writer.close()
            } catch (e: IOException) {
                throw UncheckedIOException(e)
            }
        }

        override fun toString(): String {
            return cache.toString()
        }
    }

    private class FastInput(private val inputStream: InputStream) {
        private val buffer = ByteArray(1 shl 13)
        private var bufferLength = 0
        private var bufferOffset = 0
        private var next = 0

        private fun read(): Int {
            while (bufferLength == bufferOffset) {
                bufferOffset = 0
                bufferLength = try {
                    inputStream.read(buffer)
                } catch (e: IOException) {
                    -1
                }

                if (bufferLength == -1) {
                    return -1
                }
            }

            return buffer[bufferOffset++].toInt()
        }

        private fun skipBlank() {
            while (next in 0..32) {
                next = read()
            }
        }

        fun readInt(): Int {
            var sign = 1
            skipBlank()

            if (next == '+'.code || next == '-'.code) {
                sign = if (next == '+'.code) 1 else -1
                next = read()
            }

            var value = 0

            if (sign == 1) {
                while (next in '0'.code..'9'.code) {
                    value = value * 10 + next - '0'.code
                    next = read()
                }
            } else {
                while (next in '0'.code..'9'.code) {
                    value = value * 10 - next + '0'.code
                    next = read()
                }
            }

            return value
        }
    }
}

